///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Register
 * @description Register 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Register = async function (action) {
    const sbmOptions = {
        id: "tx_fn_Register",
        method: "post",
        action: action ?? "/support/eduChrg.do",
        ref: "dma_RegisterReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_Modify
 * @description Modify 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Modify = async function (action) {
    const sbmOptions = {
        id: "tx_fn_Modify",
        method: "post",
        action: action ?? "/support/eduChrg.do",
        ref: "dma_ModifyReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_Delete
 * @description Delete 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Delete = async function (action) {
    const sbmOptions = {
        id: "tx_fn_Delete",
        method: "post",
        action: action ?? "/support/eduChrg.do",
        ref: "dma_DeleteReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name reset
 * @description reset 처리
 * @returns {void}
 * @hidden N
 */
scwin.reset = function () {
    $c.util.getComponent('dma_RegisterReq').reset();
};

/**
 * @method
 * @name print
 * @description print 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.print = async function () {
    await $c.win.print();
};

/**
 * @method
 * @name register
 * @description register 처리
 * @param {String} _submitYn _submitYn
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.register = async function (_submitYn) {
    if (!await scwin.chk()) {
        return;
    }
    $c.util.getComponent('dma_RegisterReq').set('submitYn', _submitYn);
    $c.util.getComponent('dma_RegisterReq').set('method', 'registerChargeEducation');
    await scwin.tx_fn_Register('eduChrg.do');
};

/**
 * @method
 * @name modify
 * @description modify 처리
 * @param {String} _submitYn _submitYn
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.modify = async function (_submitYn) {
    if (!await scwin.chk()) {
        return;
    }
    $c.util.getComponent('dma_RegisterReq').set('submitYn', _submitYn);
    $c.util.getComponent('dma_RegisterReq').set('method', 'modifyChrgEducation');
    await scwin.tx_fn_Modify('eduChrg.do');
};

/**
 * @method
 * @name deleteRegisterReq
 * @description delete Register Req 처리
 * @param {*} _disclsEduApplSeq _disclsEduApplSeq
 * @param {*} _disclsChrgSeq _disclsChrgSeq
 * @param {String} _submitYn _submitYn
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.deleteRegisterReq = async function (_disclsEduApplSeq, _disclsChrgSeq, _submitYn) {
    if (await $c.win.confirm("삭제 하시겠습니까?") === true) {
        $c.util.getComponent("dma_RegisterReq").set("disclsEduApplSeq", _disclsEduApplSeq);
        $c.util.getComponent('dma_RegisterReq').set('disclsChrgSeq', _disclsChrgSeq);
        $c.util.getComponent('dma_RegisterReq').set('submitYn', _submitYn);
        $c.util.getComponent('dma_RegisterReq').set('method', 'removeChargeEducation');
        await scwin.tx_fn_Delete('eduChrg.do');
    } else {
        return;
    }
};

/**
 * @method
 * @name chk
 * @description chk 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.chk = async function () {
    const frm = (document.eduForm || { elements: [] });
    if (($c.util.getComponent('ipt_chrgNm').getValue() == null ? '' : String($c.util.getComponent('ipt_chrgNm').getValue())) === '' || $c.util.getComponent('ipt_chrgNm').getValue().indexOf(" ") === "") {
        await $c.win.alert("성명을 입력해 주세요");
        $c.util.getComponent("ipt_chrgNm").focus();
        return false;
    }
    if (($c.util.getComponent('ipt_jobtitlNm').getValue() == null ? '' : String($c.util.getComponent('ipt_jobtitlNm').getValue())) === '' || $c.util.getComponent('ipt_jobtitlNm').getValue().indexOf(" ") === "") {
        await $c.win.alert("직위를 입력해 주세요");
        $c.util.getComponent("ipt_jobtitlNm").focus();
        return false;
    }
    if (($c.util.getComponent('ipt_cellphoneNo').getValue() == null ? '' : String($c.util.getComponent('ipt_cellphoneNo').getValue())) === '' || $c.util.getComponent('ipt_cellphoneNo').getValue().indexOf(" ") === "") {
        await $c.win.alert("휴대폰 번호를 입력해 주세요");
        $c.util.getComponent("ipt_cellphoneNo").focus();
        return false;
    }
    if (($c.util.getComponent('ipt_email').getValue() == null ? '' : String($c.util.getComponent('ipt_email').getValue())) === '' || $c.util.getComponent('ipt_email').getValue().indexOf(" ") === "") {
        await $c.win.alert("이메일을 입력해 주세요");
        $c.util.getComponent("ipt_email").focus();
        return false;
    }
    if ((String(((dma_pageContext.get("disableYn") ?? "")) == null ? '' : ((dma_pageContext.get("disableYn") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("disableYn") ?? "")) == null ? '' : ((dma_pageContext.get("disableYn") ?? "")))) === 'Y') {
        if (frm.disclsEduEvtAttendYn.value === "") {
            await $c.win.alert("간담회(식사) 참석여부를 선택해주세요.");
            disclsEduEvtAttendYn.focus();
            return false;
        }
    }
    return true;
};

/**
 * @method
 * @name changeDest
 * @description change Dest 처리
 * @param {Object} obj 컴포넌트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.changeDest = async function (obj) {
    const depTpCd = obj.value;
    if (depTpCd != null && depTpCd === "01") {
        await $c.win.alert("이 기간 강의는 마감되었습니다. 다른 기간의 강의를 수강해주세요.");
        return;
    } else {
        if (depTpCd != null && depTpCd === "02") {
            (document.eduForm || { elements: [] }).tmpdestTpCd.value = "사이버교육";
            $c.util.getComponent("dma_RegisterReq").set("destTpCd", "02");
        } else {
            if (depTpCd != null && depTpCd === "03") {
                (document.eduForm || { elements: [] }).tmpdestTpCd.value = "사이버교육";
                $c.util.getComponent("dma_RegisterReq").set("destTpCd", "03");
            } else {
                (document.eduForm || { elements: [] }).tmpdestTpCd.value = "";
                $c.util.getComponent("dma_RegisterReq").set("destTpCd", "");
            }
        }
    }
};
